import logging
from ta_attenuator.attenuator import Attenuator
from ta_attenuator.attenuator import RfPathAlreadyUsed


class TestAttenuator(Attenuator):
    """Class to simulate attenuator"""

    def __init__(self, min_attenuation, max_attenuation):
        super(TestAttenuator, self).__init__()
        self.min_attenuation = min_attenuation
        self.max_attenuation = max_attenuation
        self.used_ports = []
        self.current_attenuation = {}
        # Setting initial attenuation values
        for port in self.used_ports:
            self.current_attenuation[port] = 0

    def connect_attenuator_controller(self, **kwargs):
        """connect"""
        logging.info("connect to attenuator")

    def disconnect_attenuator_controller(self, **kwargs):
        """disconnect"""
        logging.info("disconnect atenuator")

    def _set_single_rf_path_decibel_attenuation(self, rf_path_address, attenuation_value_db, confirm=True):
        logging.info("Set attenuation on path {} to {} db".format(rf_path_address, attenuation_value_db))
        rf_path_address = str(rf_path_address)
        try:
            self.current_attenuation[rf_path_address] = attenuation_value_db
        except KeyError as e:
            raise KeyError("Trying to set attenuation value for rf_path {}"
                           ", which was not reserved.".format(rf_path_address) + str(e))

    def get_max_decibel_attenuation(self):
        """get max"""
        return self.max_attenuation

    def get_min_decibel_attenuation(self):
        """get min"""
        return self.min_attenuation

    def reserve_port(self, port_id):
        """Reserve port on attenuator and raise exception if it was already used"""
        if port_id in self.used_ports:
            raise RfPathAlreadyUsed('Port ID {} was already used! Already used ports = {}'.format(port_id, str(self.used_ports)))
        self.used_ports.append(port_id)
        logging.debug('Reserved ports = {}'.format(str(self.used_ports)))

    def release_port(self, port_id):
        """Release port on attenuator"""
        logging.debug('Releasing port = {}'.format(str(port_id)))
        self.used_ports.remove(port_id)
        logging.debug('Reserved ports = {}'.format(str(self.used_ports)))

    def read_rf_paths_attenuation(self, rf_paths):
        """read attenuation value in db for the first rf_path"""
        return self._read_port_value(str(rf_paths[0]))

    def _read_port_value(self, port_id):
        try:
            value_read = self.current_attenuation[str(port_id)]
        except KeyError as e:
            raise KeyError("Trying to read attenuation value for rf_path {}"
                           ", which was not reserved.".format(port_id) + str(e))
        return value_read
